{
  "name": "Yoctopuce 接近传感器",
  "name_en": "Yoctopuce Proximity Sensor",
  "manufacturer": "Yoctopuce",
  "description": "用于检测物体接近与离开状态的接近传感器，可读取接近信号值、存在状态和脉冲计数，并可配置检测阈值、迟滞以及存在/移除最小时间，适合实验装置中的到位检测、非接触触发和状态监测。",
  "description_en": "A proximity sensor for detecting object approach and removal. It can read the proximity signal value, presence state, and pulse count, and supports configuration of detection threshold, hysteresis, and minimum presence/removal times. It is suitable for in-lab position detection, non-contact triggering, and status monitoring.",
  "actions": [
    {
      "action_name": "auto-set_detectionThreshold",
      "description": "设置接近检测阈值。",
      "description_en": "Set the proximity detection threshold."
    },
    {
      "action_name": "auto-set_detectionHysteresis",
      "description": "设置接近检测迟滞。",
      "description_en": "Set the proximity detection hysteresis."
    },
    {
      "action_name": "auto-set_presenceMinTime",
      "description": "设置存在事件的最小检测时间。",
      "description_en": "Set the minimum detection time for a presence event."
    },
    {
      "action_name": "auto-set_removalMinTime",
      "description": "设置移除事件的最小检测时间。",
      "description_en": "Set the minimum detection time for a removal event."
    },
    {
      "action_name": "auto-set_pulseCounter",
      "description": "设置脉冲计数器值。",
      "description_en": "Set the pulse counter value."
    },
    {
      "action_name": "auto-set_proximityReportMode",
      "description": "设置接近报告模式。",
      "description_en": "Set the proximity report mode."
    },
    {
      "action_name": "auto-resetCounter",
      "description": "重置脉冲计数器及其计时器。",
      "description_en": "Reset the pulse counter and its timer."
    },
    {
      "action_name": "auto-nextProximity",
      "description": "枚举下一个可访问的接近传感器。",
      "description_en": "Enumerate the next accessible proximity sensor."
    }
  ],
  "tag_hints": [
    "proximity sensing",
    "presence detection",
    "non-contact trigger",
    "threshold and hysteresis",
    "pulse counting",
    "object approach/removal detection",
    "Yoctopuce"
  ]
}

